20	
21	// See the note in confirm-form.tsx — CATEGORIES carries Fragrance because it is
22	// derived from TagSchema; the picker offers the wearable families.
23	const PICKABLE = CATEGORIES.filter((c) => c !== "Fragrance");
24	
25	export type DetailItem = {
26	  id: string;
27	  name: string | null;
28	  brand: string | null;
29	  category: Tags["category"];
30	  subcategory: string | null;
31	  colors: string[];
32	  material: string | null;
33	  texture: string | null;
34	  pattern: string | null;
35	  price: number | null;
36	  formality: number | null;
37	  seasons: string[];
38	};
39	
40	export function ItemDetail({
41	  item,
42	  imageUrl,
43	  brandSuggestions,
44	}: {
45	  item: DetailItem;
46	  imageUrl: string;
47	  brandSuggestions: string[];
48	}) {
49	  const router = useRouter();
50	  const [name, setName] = useState(item.name ?? "");
51	  const [brand, setBrand] = useState(item.brand ?? "");
52	  const [material, setMaterial] = useState(item.material ?? "");
53	  const [category, setCategory] = useState<Tags["category"]>(item.category);
54	  const [formality, setFormality] = useState(item.formality ?? 3);
55	  const [seasons, setSeasons] = useState<string[]>(item.seasons);
56	  const [colors, setColors] = useState<string[]>(item.colors);
57	  const [texture, setTexture] = useState(item.texture ?? "Flat");
58	  const [pattern, setPattern] = useState(item.pattern ?? "solid");
59	  const [subcategory, setSubcategory] = useState(item.subcategory ?? "");
60	  const [price, setPrice] = useState(item.price?.toString() ?? "");
61	  const [pending, start] = useTransition();
62	  const [error, setError] = useState<string | null>(null);
63	
64	  function toggleSeason(s: string) {
65	    setSeasons((cur) => (cur.includes(s) ? cur.filter((x) => x !== s) : [...cur, s]));
66	  }
67	
68	  function save() {
69	    setError(null);
70	    start(async () => {
71	      try {
72	        await updateItem(item.id, {
73	          name: name || null,
74	          brand: brand || null,
75	          category,
76	          // "Unknown" is not in the vocabulary — it was fabricated here and
77	          // would now fail validation. "Other" is the real escape hatch.
78	          material: material || "Other",
79	          subcategory: subcategory || null,
80	          colors,
81	          texture,
82	          pattern,
83	          // An empty box means "not recorded", not zero — cost-per-wear must
84	          // not divide by a price the user never gave.
85	          price: price.trim() === "" ? null : Number(price),
86	          formality,
87	          seasons: seasons.length ? seasons : ["Spring"],
88	        });
89	        router.push("/closet");
90	      } catch (e) {
91	        setError(e instanceof Error ? e.message : "Save failed");
92	      }
93	    });
94	  }
95	
96	  function remove() {
97	    if (!confirm("Remove this piece from your closet?")) return;
98	    setError(null);
99	    start(async () => {
100	      try {
101	        await archiveItem(item.id);
102	      } catch (e) {
103	        setError(e instanceof Error ? e.message : "Failed to remove");
104	      }
105	    });
106	  }
107	
108	  return (
109	    <main className="flex flex-1 flex-col gap-5 px-6 pb-7 pt-12">
110	      <button
111	        onClick={() => router.back()}
112	        className="self-start text-2xl leading-none text-muted-foreground"
113	        aria-label="Back"
114	      >
115	        ‹
116	      </button>
117	
118	      {/* `.surface-stage` is the design's cutout stage (Fitcheck.dc.html:595 /
119	          :530) — a radial gradient lit from above, not a flat fill.
120	          The image is ABSOLUTELY positioned, not a grid item: as a grid
121	          item its `min-height:auto` forced the row past the 1.3 aspect ratio,
122	          and `max-h-full` could not save it because a percentage against an
123	          auto-sized row is indefinite and resolves to `none` — so a 970x1280
124	          cutout spilled over the fields below. Absolute + inset-0 gives
125	          object-contain a definite box to fit inside. */}
126	      <div className="relative aspect-[1.3] overflow-hidden rounded-[18px] surface-stage">
127	        {imageUrl ? (
128	          // eslint-disable-next-line @next/next/no-img-element
129	          <img
130	            src={imageUrl}
131	            alt={name}
132	            className="absolute inset-0 size-full object-contain p-6"
133	          />
134	        ) : null}
135	      </div>
136	
137	      <input
138	        value={name}
139	        onChange={(e) => setName(e.target.value)}
140	        placeholder="Name"
141	        className="rounded-[12px] border border-[--input] bg-surface-1 px-4 py-3 font-serif text-lg text-foreground outline-none focus:border-brand"
142	      />
143	
144	      <input
145	        list="brand-suggestions"
146	        value={brand}
147	        onChange={(e) => setBrand(e.target.value)}
148	        placeholder="Brand (optional)"
149	        className="-mt-2 rounded-[12px] border border-[--input] bg-surface-1 px-4 py-3 text-sm text-foreground outline-none focus:border-brand"
150	      />
151	      <datalist id="brand-suggestions">
152	        {brandSuggestions.map((b) => (
153	          <option key={b} value={b} />
154	        ))}
155	      </datalist>
156	
157	      <div>
158	        <Kicker className="mb-2 block">Category</Kicker>
159	        <div className="flex flex-wrap gap-2">
160	          {PICKABLE.map((c) => (
161	            <Chip key={c} variant="select" active={category === c} onClick={() => setCategory(c)}>
162	              {c}
163	            </Chip>
164	          ))}
165	        </div>
166	      </div>
167	
168	      <div>
169	        <Kicker className="mb-2 block">Material</Kicker>
170	        {/* A select, not free text and not chips: `material` is a constrained
171	            enum, and 27 chips ran to eight rows on a phone. */}
172	        <Select
173	          aria-label="Material"
174	          value={material}
175	          onChange={(e) => setMaterial(e.target.value)}
176	        >
177	          {MATERIALS.map((m) => (
178	            <option key={m} value={m}>
179	              {m}
180	            </option>
181	          ))}
182	        </Select>
183	      </div>
184	
185	      <div>
186	        <Kicker className="mb-2 block">Formality · {FORMALITY_LABEL[formality]}</Kicker>
187	        <div className="flex gap-2">
188	          {[1, 2, 3, 4, 5].map((n) => (
189	            <button
190	              key={n}
191	              onClick={() => setFormality(n)}
192	              className={`h-2 flex-1 rounded-full ${n <= formality ? "bg-brand" : "bg-foreground/10"}`}
193	              aria-label={`Formality ${n}`}
